63	impl PolicyConfig {
64	    pub fn load() -> Self {
65	        let candidates = config_paths();
66	        for path in &candidates {
67	            if path.exists() {
68	                if let Ok(cfg) = Self::load_from_file(path) {
69	                    return cfg;
70	                }
71	            }
72	        }
73	        Self::bundled_default()
74	    }
75	
76	    pub fn load_from_file(path: &Path) -> Result<Self> {
77	        let content = std::fs::read_to_string(path)?;
78	        let cfg: PolicyConfig = toml::from_str(&content)?;
79	        Ok(cfg)
80	    }
81	
82	    pub fn bundled_default() -> Self {
83	        Self {
84	            global: GlobalPolicy::default(),
85	            limits: vec![
86	                LimitRule {
87	                    scope: "developer".into(),
88	                    id: "*".into(),
89	                    max_usd: 500.0,
90	                    action_on_exceed: "warn".into(),
91	                },
92	            ],
93	        }
94	    }
95	}
