97	fn config_paths() -> Vec<PathBuf> {
98	    let mut paths = Vec::new();
99	    if let Ok(cwd) = std::env::current_dir() {
100	        paths.push(cwd.join(".codeflow/budget.toml"));
101	    }
102	    if let Some(config) = dirs::config_dir() {
103	        paths.push(config.join("codeflow/budget.toml"));
104	    }
105	    paths
106	}
