108	pub fn period_days(period: &str) -> i64 {
109	    match period {
110	        "daily" => 1,
111	        "weekly" => 7,
112	        "monthly" => 30,
113	        "quarterly" => 90,
114	        "yearly" => 365,
115	        _ => 30,
116	    }
117	}
