119	pub struct PolicyEngine {
120	    config: PolicyConfig,
121	}
122	
123	impl PolicyEngine {
124	    pub fn new(config: PolicyConfig) -> Self {
125	        Self { config }
126	    }
127	
128	    pub fn from_default() -> Self {
129	        Self::new(PolicyConfig::load())
130	    }
131	
132	    pub fn evaluate(
133	        &self,
134	        developer_id: &str,
135	        project_dir: &str,
136	        accumulated_dev: f64,
137	        accumulated_project: f64,
138	    ) -> Verdict {
139	        let mut worst = Verdict::Allow;
140	
141	        for rule in &self.config.limits {
142	            let (accumulated, scope_label) = match rule.scope.as_str() {
143	                "developer" => {
144	                    if rule.id != "*" && rule.id != developer_id {
145	                        continue;
146	                    }
147	                    (accumulated_dev, format!("developer:{}", developer_id))
148	                }
149	                "project" => {
150	                    let proj_name = project_dir
151	                        .rsplit(['/', '\\'])
152	                        .find(|s| !s.is_empty())
153	                        .unwrap_or(project_dir);
154	                    if rule.id != "*" && rule.id != proj_name {
155	                        continue;
156	                    }
157	                    (accumulated_project, format!("project:{}", proj_name))
158	                }
159	                _ => continue,
160	            };
161	
162	            let pct = if rule.max_usd > 0.0 {
163	                (accumulated / rule.max_usd * 100.0) as u32
164	            } else {
165	                100
166	            };
167	
168	            let block_pct = self.config.global.block_at_pct;
169	            let warn_pct = self.config.global.warn_at_pct;
170	
171	            if pct >= block_pct && rule.action_on_exceed == "block" {
172	                return Verdict::Block(format!(
173	                    "Budget exceeded for {} — ${:.2}/${:.2} ({}%)",
174	                    scope_label, accumulated, rule.max_usd, pct
175	                ));
176	            }
177	
178	            if pct >= warn_pct {
179	                let msg = format!(
180	                    "Budget warning for {} — ${:.2}/${:.2} ({}%)",
181	                    scope_label, accumulated, rule.max_usd, pct
182	                );
183	                if matches!(worst, Verdict::Allow) {
184	                    worst = Verdict::Warn(msg);
185	                }
186	            }
187	        }
188	
189	        worst
190	    }
191	
192	    pub fn config(&self) -> &PolicyConfig {
193	        &self.config
194	    }
195	}
