7	pub fn status(json: bool) -> Result<()> {
8	    let config = PolicyConfig::load();
9	    let engine = PolicyEngine::new(config.clone());
10	    let days = Some(period_days(&config.global.period));
11	
12	    let db_path = paths::data_dir().join("cost.db");
13	    let developer_id = whoami();
14	    let project_dir = std::env::current_dir()
15	        .unwrap_or_default()
16	        .to_string_lossy()
17	        .to_string();
18	
19	    let (acc_dev, acc_project) = if db_path.exists() {
20	        let store = CostStore::open(&db_path)?;
21	        let dev = store.accumulated_cost_by_dev(&developer_id, days)?;
22	        let proj = store.accumulated_cost(&project_dir, days)?;
23	        (dev, proj)
24	    } else {
25	        (0.0, 0.0)
26	    };
27	
28	    if json {
29	        let output = serde_json::json!({
30	            "developer": {
31	                "id": developer_id,
32	                "accumulated_usd": acc_dev,
33	            },
34	            "project": {
35	                "dir": project_dir,
36	                "accumulated_usd": acc_project,
37	            },
38	            "policy": {
39	                "period": config.global.period,
40	                "warn_at_pct": config.global.warn_at_pct,
41	                "block_at_pct": config.global.block_at_pct,
42	                "limits": config.limits.iter().map(|l| {
43	                    serde_json::json!({
44	                        "scope": l.scope,
45	                        "id": l.id,
46	                        "max_usd": l.max_usd,
47	                        "action": l.action_on_exceed,
48	                    })
49	                }).collect::<Vec<_>>(),
50	            },
51	            "verdict": format!("{:?}", engine.evaluate(&developer_id, &project_dir, acc_dev, acc_project)),
52	        });
53	        println!("{}", serde_json::to_string_pretty(&output)?);
54	        return Ok(());
55	    }
56	
57	    println!("╔══════════════════════════════════════════════════╗");
58	    println!("║           CODEFLOW Budget Status                 ║");
59	    println!("╠══════════════════════════════════════════════════╣");
60	    println!(
61	        "║  Period:       {:<34}║",
62	        config.global.period
63	    );
64	    println!(
65	        "║  Developer:    {:<34}║",
66	        developer_id
67	    );
68	    println!("╠══════════════════════════════════════════════════╣");
69	
70	    for rule in &config.limits {
71	        let accumulated = match rule.scope.as_str() {
72	            "developer" => acc_dev,
73	            "project" => acc_project,
74	            _ => 0.0,
75	        };
76	        let pct = if rule.max_usd > 0.0 {
77	            (accumulated / rule.max_usd * 100.0) as u32
78	        } else {
79	            100
80	        };
81	        let status_icon = if pct >= config.global.block_at_pct {
82	            "\x1b[31m■ BLOCKED\x1b[0m"
83	        } else if pct >= config.global.warn_at_pct {
84	            "\x1b[33m■ WARNING\x1b[0m"
85	        } else {
86	            "\x1b[32m■ OK\x1b[0m"
87	        };
88	
89	        println!(
90	            "║  {}:{:<8} ${:>8.2}/${:<8.2} {:>3}% {}",
91	            rule.scope,
92	            rule.id,
93	            accumulated,
94	            rule.max_usd,
95	            pct,
96	            status_icon
97	        );
98	    }
99	
100	    println!("╚══════════════════════════════════════════════════╝");
101	
102	    let verdict = engine.evaluate(&developer_id, &project_dir, acc_dev, acc_project);
103	    match verdict {
104	        codeflow_core::budget_policy::Verdict::Block(msg) => {
105	            println!("\n\x1b[31m⛔ {}\x1b[0m", msg);
106	        }
107	        codeflow_core::budget_policy::Verdict::Warn(msg) => {
108	            println!("\n\x1b[33m⚠ {}\x1b[0m", msg);
109	        }
110	        codeflow_core::budget_policy::Verdict::Allow => {
111	            println!("\n\x1b[32m✓ All budgets within limits\x1b[0m");
112	        }
113	    }
114	
115	    Ok(())
116	}
