118	pub fn history(days: Option<i64>, json: bool) -> Result<()> {
119	    let config = PolicyConfig::load();
120	    let period_d = days.unwrap_or_else(|| period_days(&config.global.period));
121	
122	    let db_path = paths::data_dir().join("cost.db");
123	    if !db_path.exists() {
124	        if json {
125	            println!("[]");
126	        } else {
127	            println!("No cost data yet.");
128	        }
129	        return Ok(());
130	    }
131	
132	    let store = CostStore::open(&db_path)?;
133	    let groups = store.by_group("day", None, Some(period_d))?;
134	
135	    if json {
136	        println!("{}", serde_json::to_string_pretty(&groups)?);
137	        return Ok(());
138	    }
139	
140	    if groups.is_empty() {
141	        println!("No spending history for the last {} days.", period_d);
142	        return Ok(());
143	    }
144	
145	    println!("\n  Spending History (last {} days)\n", period_d);
146	    println!(
147	        "  {:<12} {:>10} {:>12} {:>12} {:>6}",
148	        "Date", "Cost ($)", "Input Tok", "Output Tok", "Count"
149	    );
150	    println!("  {}", "─".repeat(56));
151	
152	    for g in &groups {
153	        println!(
154	            "  {:<12} {:>10.2} {:>12} {:>12} {:>6}",
155	            g.key,
156	            g.cost_usd,
157	            format_tokens(g.input_tokens),
158	            format_tokens(g.output_tokens),
159	            g.record_count,
160	        );
161	    }
162	
163	    let total: f64 = groups.iter().map(|g| g.cost_usd).sum();
164	    println!("  {}", "─".repeat(56));
165	    println!("  {:<12} {:>10.2}", "TOTAL", total);
166	    println!();
167	
168	    Ok(())
169	}
170	
171	fn whoami() -> String {
172	    std::env::var("USER")
173	        .or_else(|_| std::env::var("USERNAME"))
174	        .or_else(|_| std::env::var("LOGNAME"))
175	        .unwrap_or_else(|_| "unknown".to_string())
176	}
177	
178	fn format_tokens(n: u64) -> String {
179	    if n >= 1_000_000 {
180	        format!("{:.1}M", n as f64 / 1_000_000.0)
181	    } else if n >= 1_000 {
182	        format!("{:.1}K", n as f64 / 1_000.0)
183	    } else {
184	        n.to_string()
185	    }
186	}
