211	        Commands::Status => auth::status(),
212	        Commands::Logout => auth::logout(),
213	        Commands::Route { command, tokens, files } => handle_route(&command, tokens, &files),
214	
215	        Commands::Blame { file, json, session, trace } => {
216	            handle_blame(&file, json, session.as_deref(), trace)
217	        }
218	        Commands::Cost { by, pr, json, days, action } => {
219	            if let Some(act) = action {
