227	            }
228	        }
229	        Commands::Budget { action } => match action {
230	            BudgetAction::Status { json } => budget_cmd::status(json),
231	            BudgetAction::History { days, json } => budget_cmd::history(days, json),
232	        },
233	        Commands::Cache { action } => handle_cache(action),
234	        Commands::Hook { action } => handle_hook(action),
235	        Commands::Update => {
