237	            println!("commit:  {}", option_env!("CODEFLOW_GIT_SHA").unwrap_or("dev"));
238	            println!("target:  {}", env!("TARGET"));
239	            println!();
240	            println!("Update: download latest from https://github.com/codeflow-dev/codeflow/releases");
241	            Ok(())
