251	fn handle_blame(file: &str, json: bool, session: Option<&str>, trace: bool) -> anyhow::Result<()> {
252	    let db_path = paths::db_path();
253	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
254	
255	    let project_dir = std::env::current_dir().unwrap_or_default();
256	    let abs_path = if std::path::Path::new(file).is_absolute() {
257	        std::path::PathBuf::from(file)
258	    } else {
259	        project_dir.join(file)
260	    };
261	
262	    let rel_path = abs_path
263	        .strip_prefix(&project_dir)
264	        .map(|r| r.to_string_lossy().replace('\\', "/"))
265	        .unwrap_or_else(|_| file.to_string());
266	
267	    let mut records = store.query_by_file(&rel_path)?;
268	    if let Some(sid) = session {
269	        records.retain(|r| r.session_id == sid);
270	    }
271	
272	    if trace {
273	        println!("{}", codeflow_core::agent_trace::export_agent_trace(&records)?);
274	        return Ok(());
275	    }
276	
277	    if json {
278	        println!("{}", serde_json::to_string_pretty(&records)?);
279	        return Ok(());
280	    }
281	
282	    if records.is_empty() {
283	        println!("No provenance records for {}", rel_path);
284	        return Ok(());
285	    }
286	
287	    let file_content = std::fs::read_to_string(&abs_path).unwrap_or_default();
288	    let lines: Vec<&str> = file_content.lines().collect();
289	
290	    println!("Provenance: {} ({} records)\n", rel_path, records.len());
291	
292	    for rec in &records {
293	        let ts = chrono::DateTime::from_timestamp_millis(rec.timestamp_ms)
294	            .map(|dt| dt.format("%Y-%m-%d %H:%M").to_string())
295	            .unwrap_or_else(|| "?".to_string());
296	
297	        let ct_label = match rec.contributor_type {
298	            codeflow_core::provenance::ContributorType::Human => "\x1b[32mhuman\x1b[0m",
299	            codeflow_core::provenance::ContributorType::Ai => "\x1b[33mai\x1b[0m",
300	            codeflow_core::provenance::ContributorType::Mixed => "\x1b[36mmixed\x1b[0m",
301	            codeflow_core::provenance::ContributorType::Unknown => "\x1b[90munknown\x1b[0m",
302	        };
303	
304	        println!(
305	            "  {} | {} | {} | L{}-{} | {}",
306	            ts, ct_label, rec.model_id, rec.start_line, rec.end_line,
307	            &rec.code_hash[..rec.code_hash.len().min(12)]
308	        );
309	    }
310	
311	    if !lines.is_empty() {
312	        println!("\nLine attribution:");
313	        for (i, line) in lines.iter().enumerate() {
314	            let line_num = (i + 1) as u32;
315	            let attr = records.iter().find(|r| {
316	                r.start_line <= line_num && r.end_line >= line_num
317	            });
318	            let prefix = match attr {
319	                Some(r) => match r.contributor_type {
320	                    codeflow_core::provenance::ContributorType::Ai => "\x1b[33m AI \x1b[0m",
321	                    codeflow_core::provenance::ContributorType::Human => "\x1b[32m HU \x1b[0m",
322	                    codeflow_core::provenance::ContributorType::Mixed => "\x1b[36m MX \x1b[0m",
323	                    codeflow_core::provenance::ContributorType::Unknown => "\x1b[90m ?? \x1b[0m",
324	                },
325	                None => "\x1b[90m -- \x1b[0m",
326	            };
327	            println!("{:>4} |{}| {}", line_num, prefix, line);
328	        }
329	    }
330	
331	    Ok(())
332	}
