334	fn handle_route(command: &str, tokens: u64, files: &[String]) -> anyhow::Result<()> {
335	    let cmd = command.to_string();
336	    if cmd.is_empty() {
337	        anyhow::bail!("no command provided");
338	    }
339	
340	    let file_refs: Vec<&str> = files.iter().map(|f| f.as_str()).collect();
341	    let extensions = codeflow_core::router::extensions_from_paths(&file_refs);
342	
343	    let input = codeflow_core::router::RoutingInput {
344	        command: cmd.clone(),
345	        context_tokens: tokens,
346	        file_extensions: extensions,
347	        session_event_count: 0,
348	    };
349	
350	    let decision = codeflow_core::router::classify(&input);
351	
352	    println!("Command:    {}", cmd);
353	    println!("Tokens:     {}", tokens);
354	    println!("Score:      {:.2}", decision.score);
355	    println!("Complexity: {:?}", decision.complexity);
356	    println!("Route to:   {} (${}/1M tokens)", decision.tier.name(), decision.tier.cost_per_million_tokens());
357	    println!("Savings:    {:.0}% vs Opus", decision.estimated_savings_pct);
358	    if !decision.reason.is_empty() {
359	        println!("Reason:     {}", decision.reason);
360	    }
361	
362	    Ok(())
363	}
