399	fn capture_provenance(
400	    session_id: &str,
401	    tool_name: &str,
402	    tool_input: &serde_json::Value,
403	) -> anyhow::Result<()> {
404	    let db_path = paths::db_path();
405	    let store = codeflow_core::provenance::ProvenanceStore::open(&db_path)?;
406	    let keypair = codeflow_core::attestation::load_or_generate()?;
407	    let project_dir = std::env::current_dir().unwrap_or_default();
408	
409	    // Step 1: diff against previous snapshots → record provenance for prior tool's changes
410	    let changes = codeflow_core::provenance::detect_changes(
411	        &project_dir,
412	        session_id,
413	        &store,
414	        &keypair,
415	    )?;
416	    for rec in &changes {
417	        store.record(rec)?;
418	        // Update snapshot to current state after recording
419	        if let Ok(hash) = codeflow_core::content_hash::hash_file(&project_dir.join(&rec.file_path)) {
420	            let mtime = codeflow_core::util::get_file_mtime_ns(
421	                project_dir.join(&rec.file_path).to_str().unwrap_or(""),
422	            )
423	            .unwrap_or(0);
424	            store.save_snapshot(session_id, &rec.file_path, &hash, mtime)?;
425	        }
426	    }
427	
428	    // Step 2: snapshot files targeted by the current tool for next comparison
429	    let files_to_snapshot = extract_target_files(tool_name, tool_input, &project_dir);
430	    if !files_to_snapshot.is_empty() {
431	        codeflow_core::provenance::snapshot_files(
432	            &project_dir,
433	            session_id,
434	            &store,
435	            &files_to_snapshot,
436	        )?;
437	    }
438	
439	    Ok(())
440	}
441	
442	fn extract_target_files(
443	    tool_name: &str,
444	    tool_input: &serde_json::Value,
445	    project_dir: &std::path::Path,
446	) -> Vec<String> {
447	    let mut files = Vec::new();
448	    match tool_name {
449	        "Edit" | "Write" | "MultiEdit" | "NotebookEdit" => {
450	            if let Some(fp) = tool_input.get("file_path").and_then(|v| v.as_str()) {
451	                if let Some(rel) = to_relative(fp, project_dir) {
452	                    files.push(rel);
453	                }
454	            }
455	        }
456	        "Bash" => {
457	            // Bash can modify files; we can't know which ones ahead of time.
458	            // Snapshot tracked files that git reports as modified after the command runs.
459	            // Since PreToolUse fires BEFORE execution, we can only snapshot what's
460	            // already tracked. The diff-on-next-PreToolUse pattern handles detection.
461	        }
462	        _ => {}
463	    }
464	    files
465	}
