713	fn should_wrap(command: &str) -> bool {
714	    let first_word = command.split_whitespace().next().unwrap_or("");
715	    let stem = std::path::Path::new(first_word)
716	        .file_stem()
717	        .and_then(|s| s.to_str())
718	        .unwrap_or(first_word);
719	    let wrappable = [
720	        "git", "npm", "npx", "pnpm", "yarn", "cargo", "pytest", "python",
721	        "tsc", "eslint", "ls", "find", "grep", "cat", "head", "tail",
722	        "docker", "kubectl", "go", "make", "pip", "ruff", "mypy", "vitest",
723	    ];
724	    wrappable.contains(&stem)
725	}
