727	fn shell_quote(s: &str) -> String {
728	    if s.contains(' ') || s.contains('\\') || s.contains('\'') || s.contains('"') {
729	        format!("'{}'", s.replace('\'', "'\\''"))
730	    } else {
731	        s.to_string()
732	    }
733	}
