45	    pub fn open(db_path: &Path) -> Result<Self> {
46	        let conn = Connection::open(db_path)?;
47	        conn.execute_batch(
48	            "PRAGMA journal_mode=WAL;
49	             PRAGMA synchronous=NORMAL;
50	             PRAGMA busy_timeout=5000;",
51	        )?;
52	
53	        let needs_recreate = conn.query_row(
54	            "SELECT COUNT(*) FROM pragma_table_info('cost_records') WHERE name='timestamp_ms'",
55	            [],
56	            |row| row.get::<_, i64>(0),
57	        ).unwrap_or(0) == 0 && conn.query_row(
58	            "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='cost_records'",
59	            [],
60	            |row| row.get::<_, i64>(0),
61	        ).unwrap_or(0) > 0;
62	
63	        if needs_recreate {
64	            conn.execute_batch("DROP TABLE IF EXISTS cost_records;")?;
65	        }
66	
67	        conn.execute_batch(
68	            "CREATE TABLE IF NOT EXISTS cost_records (
69	                id INTEGER PRIMARY KEY AUTOINCREMENT,
70	                session_id TEXT NOT NULL,
71	                timestamp_ms INTEGER NOT NULL,
72	                model_id TEXT NOT NULL,
73	                input_tokens INTEGER NOT NULL,
74	                output_tokens INTEGER NOT NULL,
75	                cache_read_tokens INTEGER NOT NULL DEFAULT 0,
76	                cache_write_tokens INTEGER NOT NULL DEFAULT 0,
77	                cost_usd REAL NOT NULL,
78	                pr_ref TEXT NOT NULL DEFAULT '',
79	                feature_tag TEXT NOT NULL DEFAULT '',
80	                project_dir TEXT NOT NULL DEFAULT '',
81	                developer_id TEXT NOT NULL DEFAULT ''
82	            );",
83	        )?;
84	
85	        conn.execute_batch(
86	            "CREATE INDEX IF NOT EXISTS idx_cost_session ON cost_records(session_id);
87	             CREATE INDEX IF NOT EXISTS idx_cost_project ON cost_records(project_dir);
88	             CREATE INDEX IF NOT EXISTS idx_cost_pr ON cost_records(pr_ref);
89	             CREATE INDEX IF NOT EXISTS idx_cost_timestamp ON cost_records(timestamp_ms);",
90	        )?;
91	        Ok(Self { conn })
92	    }
