119	    pub fn summary(&self, project_dir: Option<&str>, days: Option<i64>) -> Result<CostSummary> {
120	        let cutoff_ms = cutoff_ms(days);
121	        let map_row = |row: &rusqlite::Row| -> rusqlite::Result<CostSummary> {
122	            Ok(CostSummary {
123	                total_cost_usd: row.get(0)?,
124	                total_input_tokens: row.get::<_, i64>(1)? as u64,
125	                total_output_tokens: row.get::<_, i64>(2)? as u64,
126	                record_count: row.get::<_, i64>(3)? as u64,
127	            })
128	        };
129	        let row = if let Some(proj) = project_dir {
130	            self.conn.query_row(
131	                "SELECT COALESCE(SUM(cost_usd),0), COALESCE(SUM(input_tokens),0),
132	                 COALESCE(SUM(output_tokens),0), COUNT(*)
133	                 FROM cost_records WHERE timestamp_ms >= ?1 AND project_dir = ?2",
134	                params![cutoff_ms, proj],
135	                map_row,
136	            )?
137	        } else {
138	            self.conn.query_row(
139	                "SELECT COALESCE(SUM(cost_usd),0), COALESCE(SUM(input_tokens),0),
140	                 COALESCE(SUM(output_tokens),0), COUNT(*)
141	                 FROM cost_records WHERE timestamp_ms >= ?1",
142	                params![cutoff_ms],
143	                map_row,
144	            )?
145	        };
146	        Ok(row)
147	    }
