149	    pub fn by_group(&self, group_col: &str, project_dir: Option<&str>, days: Option<i64>) -> Result<Vec<CostBreakdown>> {
150	        self.by_group_limit(group_col, project_dir, days, 100)
151	    }
152	
153	    pub fn by_group_limit(&self, group_col: &str, project_dir: Option<&str>, days: Option<i64>, limit: u32) -> Result<Vec<CostBreakdown>> {
154	        let col = match group_col {
155	            "pr" => "pr_ref",
156	            "dev" | "developer" => "developer_id",
157	            "model" => "model_id",
158	            "day" => "date(timestamp_ms/1000, 'unixepoch')",
159	            "session" => "session_id",
160	            _ => return Err(anyhow::anyhow!("unknown group: {}", group_col)),
161	        };
162	
163	        let cutoff_ms = cutoff_ms(days);
164	        let sql = if project_dir.is_some() {
165	            format!(
166	                "SELECT {col} as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
167	                 FROM cost_records WHERE timestamp_ms >= ?1 AND project_dir = ?2
168	                 GROUP BY grp ORDER BY SUM(cost_usd) DESC LIMIT {limit}"
169	            )
170	        } else {
171	            format!(
172	                "SELECT {col} as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
173	                 FROM cost_records WHERE timestamp_ms >= ?1 AND (?2 = '' OR project_dir = ?2)
174	                 GROUP BY grp ORDER BY SUM(cost_usd) DESC LIMIT {limit}"
175	            )
176	        };
177	
178	        let proj = project_dir.unwrap_or("").to_string();
179	        let mut stmt = self.conn.prepare(&sql)?;
180	        let rows = stmt.query_map(params![cutoff_ms, proj], |row| {
181	            Ok(CostBreakdown {
182	                key: row.get::<_, String>(0).unwrap_or_default(),
183	                cost_usd: row.get(1)?,
184	                input_tokens: row.get::<_, i64>(2)? as u64,
185	                output_tokens: row.get::<_, i64>(3)? as u64,
186	                record_count: row.get::<_, i64>(4)? as u64,
187	            })
188	        })?;
189	        let mut result = Vec::new();
190	        for r in rows {
191	            result.push(r?);
192	        }
193	        Ok(result)
194	    }
195	
196	    pub fn accumulated_cost(&self, project_dir: &str, days: Option<i64>) -> Result<f64> {
197	        let cutoff_ms = cutoff_ms(days);
198	        let cost: f64 = self.conn.query_row(
199	            "SELECT COALESCE(SUM(cost_usd), 0) FROM cost_records
200	             WHERE timestamp_ms >= ?1 AND project_dir = ?2",
201	            params![cutoff_ms, project_dir],
202	            |row| row.get(0),
203	        )?;
204	        Ok(cost)
205	    }
