207	    pub fn accumulated_cost_by_dev(&self, developer_id: &str, days: Option<i64>) -> Result<f64> {
208	        let cutoff_ms = cutoff_ms(days);
209	        let cost: f64 = self.conn.query_row(
210	            "SELECT COALESCE(SUM(cost_usd), 0) FROM cost_records
211	             WHERE timestamp_ms >= ?1 AND developer_id = ?2",
212	            params![cutoff_ms, developer_id],
213	            |row| row.get(0),
214	        )?;
215	        Ok(cost)
216	    }
