218	    pub fn by_pr(&self, pr_ref: &str, days: Option<i64>) -> Result<Vec<CostBreakdown>> {
219	        let cutoff_ms = cutoff_ms(days);
220	        let mut stmt = self.conn.prepare(
221	            "SELECT model_id as grp, SUM(cost_usd), SUM(input_tokens), SUM(output_tokens), COUNT(*)
222	             FROM cost_records WHERE timestamp_ms >= ?1 AND pr_ref = ?2
223	             GROUP BY grp ORDER BY SUM(cost_usd) DESC",
224	        )?;
225	        let rows = stmt.query_map(params![cutoff_ms, pr_ref], |row| {
226	            Ok(CostBreakdown {
227	                key: row.get::<_, String>(0).unwrap_or_default(),
228	                cost_usd: row.get(1)?,
229	                input_tokens: row.get::<_, i64>(2)? as u64,
230	                output_tokens: row.get::<_, i64>(3)? as u64,
231	                record_count: row.get::<_, i64>(4)? as u64,
232	            })
233	        })?;
234	        let mut result = Vec::new();
235	        for r in rows {
236	            result.push(r?);
237	        }
238	        Ok(result)
239	    }
