241	    pub fn record_count(&self) -> Result<u64> {
242	        let count: i64 = self.conn.query_row(
243	            "SELECT COUNT(*) FROM cost_records",
244	            [],
245	            |row| row.get(0),
246	        )?;
247	        Ok(count as u64)
248	    }
