250	    pub fn cleanup(&self, retention_days: i64) -> Result<u64> {
251	        let cutoff_ms = cutoff_ms(Some(retention_days));
252	        let changes = self.conn.execute(
253	            "DELETE FROM cost_records WHERE timestamp_ms < ?1",
254	            params![cutoff_ms],
255	        )?;
256	        Ok(changes as u64)
257	    }
258	}
259	
260	fn cutoff_ms(days: Option<i64>) -> i64 {
261	    let days = days.unwrap_or(90);
262	    let now_ms = chrono::Utc::now().timestamp_millis();
263	    now_ms - (days * 86_400_000)
264	}
